    if not courses:
        return set()
    # 将每个课程的学生列表转换为集合
    sets = [set(students) for students in courses.values()]
    # 从第一个集合开始，依次取交集
    common = sets[0]
    for s in sets[1:]:
        common = common & s
    return common

